const products = $input.first().json.products || [];

if (!products.length) {
  return [{ json: { result: 'No books found matching that search. Try searching by a different title or author name. You can also browse all books at yellowfeatherbookstore.in' } }];
}

const lines = products.map(p => {
  const v = p.variants?.[0];
  const mrp = v?.compare_at_price ? `₹${v.compare_at_price}` : null;
  const price = v?.price ? `₹${v.price}` : 'N/A';
  const priceStr = mrp && mrp !== price ? `${price} (MRP: ${mrp})` : price;

  const qty = v?.inventory_quantity ?? -1;
  let stockStr;
  if (!v?.inventory_management) {
    stockStr = '✅ Available';
  } else if (qty > 5) {
    stockStr = `✅ In Stock (${qty} copies)`;
  } else if (qty > 0) {
    stockStr = `⚠️ Only ${qty} left`;
  } else {
    stockStr = '❌ Out of Stock';
  }

  // Extract author from tags (tagged as "author:Name" or just plain tags)
  const authorTag = (p.tags || '').split(',').map(t => t.trim()).find(t => t.toLowerCase().startsWith('author:'));
  const author = authorTag ? authorTag.replace(/^author:/i, '').trim() : null;

  return [
    `📖 ${p.title}`,
    author ? `   Author: ${author}` : '',
    `   Price: ${priceStr}`,
    `   Stock: ${stockStr}`
  ].filter(Boolean).join('\n');
});

const result = lines.join('\n\n');
return [{ json: { result } }];
